#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: PrairieRun · Google Calendar Chrome-extension OAuth
# Fixes Error 400: redirect_uri_mismatch by matching the OAuth client's
# Item ID to the ID Helium/Chrome shows for the loaded unpacked extension.
# ──────────────────────────────────────────────────────────────────────────

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="$ROOT/.env.local"
OAUTH_CONFIG="$ROOT/extension/oauth-config.js"
PINNED_EXT_ID="fgncndgfndbloldillplemcfoifapnnf"
# GCP project that already has Calendar API + PrairieRun Calendar client.
GCP_PROJECT="${GCP_PROJECT:-email-client-512819}"

write_oauth_client_id() {
  local client_id="$1"
  node -e '
const fs = require("fs");
const path = process.argv[1];
const clientId = process.argv[2];
if (!/^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$/i.test(clientId)) {
  console.error("Client ID does not look like a Google OAuth client ID.");
  process.exit(1);
}
const next = `// PrairieRun Google OAuth client configuration.
//
// Chrome-extension OAuth client for Calendar API read/write. End users never
// edit this file. Item ID on the client must match the loaded extension ID.
// No client secret belongs here. Never commit tokens.
(function () {
  globalThis.PrairieRunOAuthConfig = {
    clientId: ${JSON.stringify(clientId)},
  };
})();
`;
fs.writeFileSync(path, next);
console.log("wrote", path);
' "$OAUTH_CONFIG" "$client_id"
  printf '  %s✓ wrote%s clientId → extension/oauth-config.js\n' "$GREEN" "$RESET"
}

TOTAL_STAGES=7

banner "PrairieRun · Google Calendar OAuth"

stage "Copy your real extension ID"
say "redirect_uri_mismatch means Google's Chrome-extension client Item ID"
say "does not match the ID of the PrairieRun install you just clicked Sign in on."
say ""
say "Where to get the ID (this is the only correct source):"
step "Open the extensions page in the SAME browser that loads PrairieRun:"
note "  Helium:  helium://extensions   (or chrome://extensions)"
note "  Chrome:  chrome://extensions"
note "  Brave:   brave://extensions"
step "Turn on Developer mode (top-right toggle) if it is off."
step "Find the card named PrairieRun (Load unpacked)."
step "Under the name, copy the ID — a 32-character string of letters a–p only."
note "  Example shape: mnamlokfacnefhemchmhgnhcicolbdki"
note "  Manifest pin expects: $PINNED_EXT_ID"
note "  If Helium still shows a different ID, use Helium's ID (not the pin)."
say ""
warn "Do NOT invent an ID. Do NOT use a Chrome Web Store listing ID unless that is what the card shows."
ask EXTENSION_ID "Paste the PrairieRun ID from the extensions page:"
EXTENSION_ID=$(printf '%s' "$EXTENSION_ID" | tr '[:upper:]' '[:lower:]' | tr -d '[:space:]')
if [[ ! "$EXTENSION_ID" =~ ^[a-p]{32}$ ]]; then
  warn "That is not a Chrome extension ID (need exactly 32 chars a–p)."
  exit 1
fi
write_env PRAIRIERUN_EXTENSION_ID "$EXTENSION_ID"
REDIRECT_URI="https://${EXTENSION_ID}.chromiumapp.org/"
note "Google will validate redirect: ${REDIRECT_URI}oauth2"
if [[ "$EXTENSION_ID" != "$PINNED_EXT_ID" ]]; then
  warn "Loaded ID ≠ pinned manifest key ($PINNED_EXT_ID)."
  say "That is OK — we will register a client for the ID you pasted."
  say "Optional later: Remove + Load unpacked from extension/ so the pin applies."
fi

stage "Pick / open the Google Cloud project"
say "Use a GCP project you own (Calendar API must be enabled there)."
open_url "https://console.cloud.google.com/home/dashboard?project=${GCP_PROJECT}"
step "Confirm the project picker shows a project you can edit (default: ${GCP_PROJECT})."
step "If you need a different project, switch it in the top bar, then continue."
ask GCP_PROJECT_ID "GCP project ID (Enter keeps ${GCP_PROJECT}):"
[[ -z "$GCP_PROJECT_ID" ]] && GCP_PROJECT_ID="$GCP_PROJECT"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"

stage "Enable Google Calendar API"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com?project=${GCP_PROJECT_ID}"
step "If the button says Enable, click it and wait until it shows Manage."
step "If it already says Manage, you are done here."
pause "Press Enter once Calendar API is enabled"

stage "Consent screen + Calendar scope + test user"
say "Testing mode only allows listed test users (e.g. greenworldwins@gmail.com)."
open_url "https://console.cloud.google.com/auth/branding?project=${GCP_PROJECT_ID}"
step "App name: PrairieRun · User support email: your Google address · Save if needed."
open_url "https://console.cloud.google.com/auth/scopes?project=${GCP_PROJECT_ID}"
step "Add or remove scopes → filter Google Calendar API."
step "Check ONLY this one scope (uncheck everything else):"
note "  https://www.googleapis.com/auth/calendar"
note "  UI label: See, edit, share, and permanently delete all the calendars…"
step "Do NOT use calendar.app.created + calendar.calendarlist alone — the"
step "extension still requests full calendar, and /colors + legacy calendars need it."
step "Update → Save."
open_url "https://console.cloud.google.com/auth/audience?project=${GCP_PROJECT_ID}"
step "Under Test users → Add users → add the SAME Google account you use to Sign in."
pause "Press Enter once branding, calendar scope, and test user are saved"

stage "Create Calendar OAuth client (Chrome/Brave)"
say "Do NOT reuse the Convex Auth Web client (AUTH_GOOGLE_ID). Calendar needs"
say "its own client. Helium cannot register Google OAuth redirects — use"
say "Chrome or Brave for Sign in with Google; Helium keeps the feed URL."
say ""
say "Preferred: Chrome Extension client"
open_url "https://console.cloud.google.com/auth/clients/create?project=${GCP_PROJECT_ID}"
step "Application type: Chrome Extension"
step "Name: PrairieRun Calendar"
step "Item ID (exact):"
note "  $EXTENSION_ID"
step "Create → copy Client ID."
say ""
say "Fallback: Web application client — Authorized redirect URIs, ONLY:"
note "  https://${EXTENSION_ID}.chromiumapp.org/oauth2"
warn "Do not add .qjz9zk / Helium fake hosts — Google rejects those TLDs."
ask GOOGLE_CALENDAR_CLIENT_ID "Paste the Calendar Client ID (not Convex Auth):"
GOOGLE_CALENDAR_CLIENT_ID=$(printf '%s' "$GOOGLE_CALENDAR_CLIENT_ID" | tr -d '[:space:]')
if [[ -z "$GOOGLE_CALENDAR_CLIENT_ID" || "$GOOGLE_CALENDAR_CLIENT_ID" != *.apps.googleusercontent.com ]]; then
  warn "Client ID looks wrong — re-run and paste the full …apps.googleusercontent.com value."
  exit 1
fi
EXISTING_AUTH_ID=$(_existing AUTH_GOOGLE_ID || true)
if [[ -n "$EXISTING_AUTH_ID" && "$GOOGLE_CALENDAR_CLIENT_ID" == "$EXISTING_AUTH_ID" ]]; then
  warn "That is your Convex AUTH_GOOGLE_ID. Calendar must be a different client."
  exit 1
fi
write_env GOOGLE_CALENDAR_CLIENT_ID "$GOOGLE_CALENDAR_CLIENT_ID"
write_oauth_client_id "$GOOGLE_CALENDAR_CLIENT_ID"

stage "Rebuild Chrome manifest + reload unpacked"
say "oauth-config.js is updated. Reload so the service worker picks up the client ID."
if [[ -f "$ROOT/extension/manifest.base.json" ]]; then
  if node "$ROOT/build-manifest.js" --target=chrome; then
    note "chrome manifest rebuilt"
  else
    warn "build-manifest failed — continue; oauth-config.js is what Sign in reads"
  fi
fi
step "In Helium/Chrome: helium://extensions or chrome://extensions"
step "On PrairieRun → Reload (circular arrow). Confirm ID still matches:"
note "  $EXTENSION_ID"
step "If ID changed after reload, stop and re-run this wizard with the new ID."
pause "Press Enter after Reload"

stage "Sign in with Google"
say "This is the Calendar API path (read/write), not the anonymous feed URL."
step "Open the PrairieRun dashboard (toolbar button)."
step "Google Calendar card → Sign in with Google."
step "Approve Calendar access for your test-user Google account."
step "After success you should see Signed in, plus per-course / one PrairieRun radios."
if confirm "Did Sign in with Google succeed (no redirect_uri_mismatch)?"; then
  say "Calendar OAuth is wired. Sync now to create calendars/events."
else
  warn "Still failing: re-check Item ID on the OAuth client equals $EXTENSION_ID"
  note "  Expected redirect host: ${EXTENSION_ID}.chromiumapp.org"
  SKIPPED+=("Sign-in smoke (fix Item ID / create a fresh Chrome Extension client / re-run wizard)")
fi

finish
say "Anonymous users keep Calendar feed → Copy feed URL."
say "Signed-in Google Calendar uses this Chrome-extension client for API R/W."
note "Client ID file: extension/oauth-config.js"
note "Saved values: $ENV_FILE"
